import math, numpy as np

def mul(a,b):
 w,x,y,z=a; W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
def rot(q):
 w,x,y,z=q
 return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def axisq(a,t):
 a=np.array(a)/np.linalg.norm(a);return np.r_[math.cos(t/2),a*math.sin(t/2)]
qd=np.array([0,-2**-.5,2**-.5,0.])
yaw=axisq([0,0,1],math.radians(75))
qg=mul(yaw,qd);R=rot(qg); jaw=R[:,1]
u=np.array([.968,-.249,0]);
print('qg',qg,'axes',R,'jaw',jaw,'dot',jaw@u)
qu=mul(axisq(jaw,math.pi/2),qg)
print('qu',qu,'axes',rot(qu),'u rotated',rot(axisq(jaw,math.pi/2))@u)
